-- Immutable, data-free baseline for a newly created FarmGuardian database.
-- Do not edit this file after it has been applied; add a new versioned migration instead.
-- This V1 intentionally represents the legacy refresh_tokens schema. V2 replaces it.

CREATE TABLE users (
    user_id BIGINT NOT NULL AUTO_INCREMENT,
    created_at DATETIME(6) NULL,
    deleted_at DATETIME(6) NULL,
    updated_at DATETIME(6) NULL,
    email VARCHAR(255) NULL,
    password VARCHAR(255) NULL,
    role ENUM('ADMIN', 'USER') NULL,
    CONSTRAINT pk_users PRIMARY KEY (user_id),
    CONSTRAINT uk_users_email UNIQUE (email)
);

CREATE TABLE devices (
    device_id BIGINT NOT NULL AUTO_INCREMENT,
    created_at DATETIME(6) NULL,
    deleted_at DATETIME(6) NULL,
    updated_at DATETIME(6) NULL,
    alias VARCHAR(10) NULL,
    device_uuid VARCHAR(255) NOT NULL,
    latitude DECIMAL(10, 7) NULL,
    longitude DECIMAL(10, 7) NULL,
    status ENUM('AVAILABLE', 'CONNECTED', 'INACTIVE') NOT NULL,
    target_crop ENUM(
        'BEAN',
        'CABBAGE',
        'CHILI_PEPPER',
        'CORN',
        'CUCUMBER',
        'GREEN_ONION',
        'NAPA_CABBAGE',
        'PERILLA_SEEDS',
        'POTATO',
        'RADISH'
    ) NULL,
    user_id BIGINT NULL,
    CONSTRAINT pk_devices PRIMARY KEY (device_id),
    CONSTRAINT uk_devices_device_uuid UNIQUE (device_uuid),
    CONSTRAINT fk_devices_user FOREIGN KEY (user_id) REFERENCES users (user_id)
);

CREATE INDEX idx_devices_user_id ON devices (user_id);

CREATE TABLE fcm_tokens (
    fcm_token_id BIGINT NOT NULL AUTO_INCREMENT,
    platform ENUM('ANDROID', 'IOS') NOT NULL,
    token_value VARCHAR(255) NOT NULL,
    user_id BIGINT NOT NULL,
    CONSTRAINT pk_fcm_tokens PRIMARY KEY (fcm_token_id),
    CONSTRAINT uk_fcm_tokens_token_value UNIQUE (token_value),
    CONSTRAINT fk_fcm_tokens_user FOREIGN KEY (user_id) REFERENCES users (user_id)
);

CREATE INDEX idx_fcm_tokens_user_id ON fcm_tokens (user_id);

CREATE TABLE origin_images (
    origin_image_id BIGINT NOT NULL AUTO_INCREMENT,
    analysis_result JSON NULL,
    cloud_url VARCHAR(512) NOT NULL,
    created_at DATETIME(6) NULL,
    height INT NOT NULL,
    width INT NOT NULL,
    device_id BIGINT NOT NULL,
    CONSTRAINT pk_origin_images PRIMARY KEY (origin_image_id),
    CONSTRAINT fk_origin_images_device FOREIGN KEY (device_id) REFERENCES devices (device_id)
);

CREATE INDEX idx_origin_images_device_id ON origin_images (device_id);

CREATE TABLE refresh_tokens (
    id BIGINT NOT NULL AUTO_INCREMENT,
    client_uuid VARCHAR(255) NOT NULL,
    token VARCHAR(255) NOT NULL,
    user_id BIGINT NOT NULL,
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT uk_refresh_tokens_token UNIQUE (token),
    CONSTRAINT uk_refresh_tokens_user_client UNIQUE (user_id, client_uuid),
    CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users (user_id)
);
